import React, { useState, useCallback, useEffect } from 'react';
import { SeoArticle } from './types';
import { generateSeoArticle, generateSuggestedTopics } from './services/geminiService';
import SeoForm from './components/SeoForm';
import SeoResult from './components/SeoResult';
import Loader from './components/Loader';

// Heroicon for sparkles effect
const SparklesIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-8 h-8">
        <path strokeLinecap="round" strokeLinejoin="round" d="M9.813 15.904 9 18.75l-.813-2.846a4.5 4.5 0 0 0-3.09-3.09L2.25 12l2.846-.813a4.5 4.5 0 0 0 3.09-3.09L9 5.25l.813 2.846a4.5 4.5 0 0 0 3.09 3.09L15.75 12l-2.846.813a4.5 4.5 0 0 0-3.09 3.09ZM18.259 8.715 18 9.75l-.259-1.035a3.375 3.375 0 0 0-2.455-2.456L14.25 6l1.036-.259a3.375 3.375 0 0 0 2.455-2.456L18 2.25l.259 1.035a3.375 3.375 0 0 0 2.456 2.456L21.75 6l-1.035.259a3.375 3.375 0 0 0-2.456 2.456Z" />
    </svg>
);

const RefreshIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-5 h-5">
        <path strokeLinecap="round" strokeLinejoin="round" d="M16.023 9.348h4.992v-.001M2.985 19.644v-4.992m0 0h4.992m-4.993 0 3.181 3.183a8.25 8.25 0 0 0 13.803-3.7M4.031 9.865a8.25 8.25 0 0 1 13.803-3.7l3.181 3.182m0-4.991v4.99" />
    </svg>
);

export default function App() {
    const [topic, setTopic] = useState<string>('');
    const [seoArticle, setSeoArticle] = useState<SeoArticle | null>(null);
    const [isLoading, setIsLoading] = useState<boolean>(false);
    const [error, setError] = useState<string | null>(null);
    const [suggestedTopics, setSuggestedTopics] = useState<string[]>([]);
    const [isLoadingSuggestions, setIsLoadingSuggestions] = useState<boolean>(true);

    const fetchSuggestedTopics = useCallback(async () => {
        setIsLoadingSuggestions(true);
        try {
            const topics = await generateSuggestedTopics();
            setSuggestedTopics(topics);
        } catch (err) {
            console.error("Failed to fetch suggested topics:", err);
            setSuggestedTopics([
                'Làm thế nào để xây dựng sự tự tin trong đời sống lứa đôi?',
                'Tầm quan trọng của giao tiếp cảm xúc trong tình dục',
                'Wellness: Xu hướng sử dụng sản phẩm hỗ trợ sức khỏe sinh lý hiện đại'
            ]);
        } finally {
            setIsLoadingSuggestions(false);
        }
    }, []);

    useEffect(() => {
        fetchSuggestedTopics();
    }, [fetchSuggestedTopics]);

    const handleGenerate = useCallback(async () => {
        if (!topic.trim()) {
            setError('Vui lòng nhập chủ đề cho bài viết.');
            return;
        }

        setIsLoading(true);
        setError(null);
        setSeoArticle(null);

        try {
            const article = await generateSeoArticle(topic);
            setSeoArticle(article);
            fetchSuggestedTopics();
        } catch (err) {
            console.error(err);
            setError(err instanceof Error ? err.message : 'Đã xảy ra lỗi không xác định khi tạo bài viết. Vui lòng kiểm tra lại sau.');
        } finally {
            setIsLoading(false);
        }
    }, [topic, fetchSuggestedTopics]);

    return (
        <div className="min-h-screen bg-slate-900 text-slate-200 font-sans">
            <main className="container mx-auto px-4 py-8 md:py-12">
                <header className="text-center mb-10">
                    <div className="inline-flex items-center gap-4 mb-4">
                        <SparklesIcon />
                        <h1 className="text-4xl md:text-5xl font-bold bg-gradient-to-r from-purple-400 to-indigo-400 text-transparent bg-clip-text">
                            Sexual Wellness AI
                        </h1>
                    </div>
                    <p className="text-lg text-slate-400 max-w-2xl mx-auto">
                        Tạo bài viết sức khỏe tình dục cao cấp, tối ưu SEO, quảng bá sản phẩm tinh tế và phù hợp với văn hóa Việt Nam. Giải pháp an toàn, tránh lỗi nhạy cảm của Google.
                    </p>
                </header>

                <div className="max-w-3xl mx-auto bg-slate-800/50 rounded-2xl shadow-lg p-6 md:p-8 border border-slate-700">
                    <SeoForm
                        topic={topic}
                        setTopic={setTopic}
                        onSubmit={handleGenerate}
                        isLoading={isLoading}
                    />
                </div>

                <div className="max-w-3xl mx-auto mt-12 border-t border-slate-700 pt-8">
                    <div className="flex flex-col md:flex-row justify-between items-center mb-6 gap-4">
                        <h2 className="text-xl font-semibold text-slate-300">Gợi ý chủ đề "Wellness" thịnh hành</h2>
                        <button
                            onClick={fetchSuggestedTopics}
                            disabled={isLoadingSuggestions}
                            className="flex items-center gap-2 text-sm text-indigo-400 hover:text-indigo-300 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
                        >
                            <RefreshIcon />
                            {isLoadingSuggestions ? 'Đang tìm ý tưởng...' : 'Làm mới gợi ý'}
                        </button>
                    </div>

                    {isLoadingSuggestions ? (
                         <div className="grid grid-cols-1 md:grid-cols-2 gap-4 animate-pulse">
                            {[1, 2, 3, 4, 5, 6].map((i) => (
                                <div key={i} className="h-14 bg-slate-800 rounded-lg"></div>
                            ))}
                         </div>
                    ) : (
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                            {suggestedTopics.map((sTopic, index) => (
                                <button
                                    key={index}
                                    onClick={() => setTopic(sTopic)}
                                    className="text-left px-4 py-3 bg-slate-800 border border-slate-700 hover:border-indigo-500/50 hover:bg-slate-750 text-slate-300 rounded-lg text-sm transition-all duration-200 group"
                                >
                                    <span className="group-hover:text-indigo-400 transition-colors line-clamp-2">{sTopic}</span>
                                </button>
                            ))}
                        </div>
                    )}
                </div>

                {error && (
                    <div className="max-w-3xl mx-auto mt-8 bg-red-900/50 border border-red-700 text-red-300 px-4 py-3 rounded-lg text-center">
                        <p>{error}</p>
                    </div>
                )}

                <div className="mt-12">
                    {isLoading && <Loader />}
                    {seoArticle && <SeoResult article={seoArticle} />}
                </div>

                 <footer className="text-center mt-16 text-slate-500 text-sm">
                    <p>Hệ thống AI chuyên dụng cho Adult Wellness & SEO Việt Nam. Tuân thủ quy tắc văn hóa & an toàn nội dung.</p>
                </footer>
            </main>
        </div>
    );
}

import { GoogleGenAI, Type, HarmCategory, HarmBlockThreshold, Modality } from '@google/genai';
import { SeoArticle } from '../types';

if (!process.env.API_KEY) {
    throw new Error("API_KEY environment variable not set. Please make sure it's available.");
}

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const safetySettings = [
  {
    category: HarmCategory.HARM_CATEGORY_HARASSMENT,
    threshold: HarmBlockThreshold.BLOCK_NONE,
  },
  {
    category: HarmCategory.HARM_CATEGORY_HATE_SPEECH,
    threshold: HarmBlockThreshold.BLOCK_NONE,
  },
  {
    category: HarmCategory.HARM_CATEGORY_SEXUALLY_EXPLICIT,
    threshold: HarmBlockThreshold.BLOCK_NONE,
  },
  {
    category: HarmCategory.HARM_CATEGORY_DANGEROUS_CONTENT,
    threshold: HarmBlockThreshold.BLOCK_NONE,
  },
];

async function generateImageWithFlash(prompt: string): Promise<string | null> {
    try {
        const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash-image',
            contents: {
                parts: [{ text: prompt }],
            },
            config: {
                responseModalities: [Modality.IMAGE],
            },
            safetySettings: safetySettings,
        });

        if (response.candidates && response.candidates[0].content.parts) {
            for (const part of response.candidates[0].content.parts) {
                if (part.inlineData) {
                    const base64ImageBytes: string = part.inlineData.data;
                    const mimeType = part.inlineData.mimeType;
                    return `data:${mimeType};base64,${base64ImageBytes}`;
                }
            }
        }
        return null;
    } catch (error) {
        console.error("Error generating image:", error);
        return null;
    }
}

const articleSchema = {
    type: Type.OBJECT,
    properties: {
        title: { type: Type.STRING, description: 'Tiêu đề chuẩn SEO, hấp dẫn, tinh tế theo phong cách Wellness.' },
        content: { type: Type.STRING, description: "Nội dung chi tiết, chuẩn SEO. Sử dụng **chữ in đậm** cho heading. Chèn prompt ảnh định dạng `[PROMPT: description]`. Nội dung phải cực kỳ văn minh, giáo dục." },
        tags: { type: Type.ARRAY, items: { type: Type.STRING } },
        relatedKeywords: { type: Type.ARRAY, items: { type: Type.STRING } },
        imagePrompt: { type: Type.STRING, description: 'Prompt ảnh đại diện: Chuyên nghiệp, y khoa hoặc lifestyle cao cấp.' },
        urlSlug: { type: Type.STRING },
        metaKeywords: { type: Type.STRING },
        metaDescription: { type: Type.STRING, description: 'Mô tả meta 150-160 ký tự, chứa từ khóa chính, lôi cuốn.' },
        htmlHeader: { type: Type.STRING, description: 'JSON-LD Schema markup.' },
    },
    required: ['title', 'content', 'tags', 'relatedKeywords', 'imagePrompt', 'urlSlug', 'metaKeywords', 'metaDescription', 'htmlHeader'],
};

export async function generateSuggestedTopics(): Promise<string[]> {
    const topicsSchema = {
        type: Type.OBJECT,
        properties: {
            topics: { type: Type.ARRAY, items: { type: Type.STRING } }
        },
        required: ['topics'],
    };

    const searchAngles = [
        "Sức khỏe tình dục nam giới & bản lĩnh bền bỉ (Góc nhìn y khoa)",
        "Sexual Wellness cho nữ giới: Tự do khám phá & hạnh phúc",
        "Gia tăng sự kết nối cảm xúc và hâm nóng tình cảm lứa đôi",
        "Giáo dục giới tính văn minh cho người trưởng thành",
        "Tâm lý học về sự thỏa mãn và hạnh phúc trong hôn nhân",
        "Wellness: Cách tích hợp các thiết bị hỗ trợ vào đời sống khỏe mạnh",
        "Dinh dưỡng và bài tập cải thiện chức năng sinh lý",
        "Vượt qua rào cản tâm lý và tự tin trong phòng ngủ",
        "Nghệ thuật giao tiếp về những nhu cầu thầm kín",
        "Sức khỏe sinh lý cho lứa tuổi trung niên: Giữ lửa yêu"
    ];

    const randomAngle = searchAngles[Math.floor(Math.random() * searchAngles.length)];

    const systemInstruction = `Bạn là chuyên gia biên tập cho một trang web Sexual Wellness cao cấp tại Việt Nam.
    Nhiệm vụ: Gợi ý 10 tiêu đề bài viết BLOG độc đáo về "${randomAngle}".

    YÊU CẦU:
    1. **Tinh tế & Văn minh**: Tuyệt đối không dùng từ ngữ thô tục, rẻ tiền. Sử dụng phong cách chuyên nghiệp, giáo dục.
    2. **Tối ưu SEO**: Tiêu đề phải chứa từ khóa tiềm năng nhưng tự nhiên.
    3. **Phù hợp văn hóa**: Hiểu tâm lý người Việt (kín đáo nhưng có nhu cầu tìm hiểu kiến thức đúng đắn).
    4. **Tránh nhạy cảm**: Tránh các tiêu đề khiến Google bot đánh dấu là nội dung khiêu dâm (Pornographic). Hãy tập trung vào SỨC KHỎE (Health) và HẠNH PHÚC (Well-being).`;

    try {
        const response = await ai.models.generateContent({
            model: "gemini-3-flash-preview",
            contents: `Hãy gợi ý 10 chủ đề SEO độc đáo về "${randomAngle}" phù hợp với website bán đồ chơi tình dục cao cấp tại Việt Nam nhưng viết theo hướng giáo dục và wellness.`,
            config: {
                systemInstruction: systemInstruction,
                responseMimeType: "application/json",
                responseSchema: topicsSchema,
                temperature: 1.0,
            },
            safetySettings: safetySettings,
        });

        const parsedResponse: { topics: string[] } = JSON.parse(response.text);
        return parsedResponse.topics;
    } catch (e) {
        console.error("Error generating topics:", e);
        return [
            "Cách cải thiện sức khỏe sinh lý tự nhiên",
            "Tâm lý học và sự gắn kết trong tình yêu",
            "Hướng dẫn chăm sóc bản thân và Wellness"
        ];
    }
}

export async function generateSeoArticle(topic: string): Promise<SeoArticle> {
    const keywordsToInclude = [
        "thiết bị hỗ trợ sức khỏe tình dục", "sản phẩm chăm sóc wellness", 
        "gel bôi trơn cao cấp", "bao cao su an toàn", "máy rung massage thư giãn",
        "dụng cụ hỗ trợ tăng cường cảm giác", "bí quyết hạnh phúc lứa đôi"
    ];

    const systemInstruction = `Bạn là Chuyên gia Nội dung (Content Expert) cho một thương hiệu đồ chơi tình dục (Sex Toys) cao cấp tại Việt Nam.

    MỤC TIÊU: Viết bài viết SEO chất lượng cao để vừa giáo dục người dùng, vừa quảng bá sản phẩm MỘT CÁCH TINH TẾ.

    QUY TẮC "VĂN HÓA VIỆT NAM" & "GOOGLE SAFE":
    1. **Ngôn từ**: Sử dụng từ ngữ chuyên môn y khoa hoặc từ ngữ hoa mỹ, lịch sự. Thay vì dùng từ thô tục, hãy dùng: "sự thăng hoa", "kết nối lứa đôi", "vùng nhạy cảm", "trải nghiệm wellness", "giải phóng cảm xúc".
    2. **Lồng ghép sản phẩm**: Không bán hàng trực tiếp kiểu "Mua ngay máy rung này". Hãy viết theo hướng: "Việc sử dụng các thiết bị hỗ trợ như máy rung massage không chỉ giúp cải thiện tâm trạng mà còn là giải pháp hiệu quả để khám phá bản thân, giải tỏa căng thẳng sau ngày dài...". 
    3. **Cấu trúc bài viết**: Phải có phần mở đầu nêu vấn đề, phần thân bài giải thích khoa học/tâm lý, và phần kết luận đưa ra lời khuyên (kèm sản phẩm).
    4. **Tránh lỗi Google**: Tránh nhồi nhét từ khóa nhạy cảm. Tập trung vào giá trị thông tin. Google ưu tiên các bài viết "Health & Wellness".
    5. **Hình ảnh**: Prompt ảnh phải mang tính lifestyle, sang trọng (ví dụ: một phòng ngủ ấm cúng, một cặp đôi nắm tay, hoặc sơ đồ giải phẫu y khoa sạch sẽ). Tuyệt đối không prompt ảnh hở hang.

    ĐỊNH DẠNG:
    - Không dùng '#'. Dùng **chữ in đậm** cho Heading (H2, H3).
    - Sau mỗi heading quan trọng, chèn \`[PROMPT: detailed English description]\`.`;

    const prompt = `
    Hãy viết bài viết chuẩn SEO chuyên sâu về: "${topic}".
    Lồng ghép tinh tế các từ khóa: ${keywordsToInclude.join(', ')}.
    Đảm bảo nội dung lôi cuốn, hữu ích cho cộng đồng và an toàn với các thuật toán của Google.
    `;

    try {
        const textResponse = await ai.models.generateContent({
            model: "gemini-3-pro-preview",
            contents: prompt,
            config: {
                systemInstruction: systemInstruction,
                responseMimeType: "application/json",
                responseSchema: articleSchema,
                temperature: 0.7,
            },
            safetySettings: safetySettings,
        });

        const parsedArticle: SeoArticle = JSON.parse(textResponse.text);

        // Process images
        const contentWithPrompts = parsedArticle.content;
        const promptRegex = /\[PROMPT:\s*(.*?)\s*\]/g;
        const prompts = [...contentWithPrompts.matchAll(promptRegex)];

        if (prompts.length > 0) {
            const imageResults = await Promise.all(prompts.map(match => {
                return generateImageWithFlash(match[1]).then(imageUrl => ({
                    originalPrompt: match[0],
                    imageUrl: imageUrl,
                    promptText: match[1]
                }));
            }));

            let finalContent = contentWithPrompts;
            for (const result of imageResults) {
                const imgTag = result.imageUrl 
                    ? `<img src="${result.imageUrl}" alt="${result.promptText.replace(/"/g, '&quot;')}" style="width:100%; border-radius: 12px; margin: 2rem 0; display: block;" />`
                    : `<!-- Image failed to load -->`;
                finalContent = finalContent.replace(result.originalPrompt, `\n${imgTag}\n`);
            }
            parsedArticle.content = finalContent;
        }

        // Featured Image
        if (parsedArticle.imagePrompt) {
            const imageUrl = await generateImageWithFlash(parsedArticle.imagePrompt);
            parsedArticle.imageUrl = imageUrl || 'https://placehold.co/1200x630/0f172a/e2e8f0/png?text=Sexual+Wellness+Illustration';
        }

        return parsedArticle;
    } catch (e) {
        console.error("Gemini API Error:", e);
        throw new Error("Không thể tạo bài viết. Có thể chủ đề quá nhạy cảm hoặc lỗi kết nối. Hãy thử thay đổi cách diễn đạt chủ đề.");
    }
}

