export async function generateSeoArticle(topic: string): Promise<SeoArticle> {
    const systemInstruction = `Bạn là Chuyên gia Tư vấn Tình dục học và Content Marketing đỉnh cao cho thương hiệu Adult Toy cao cấp.

    NHIỆM VỤ: Viết một bài viết BLOG cực kỳ chuyên sâu, độ dài trên 1500 chữ, tối ưu SEO tuyệt đối cho từ khóa liên quan đến "${topic}".

    CHIẾN LƯỢC NỘI DUNG:
    1. **Mở đầu (Hook)**: Nêu bật vấn đề thực tế (căng thẳng, giảm ham muốn, sự nhàm chán trong hôn nhân) và dẫn dắt đến giải pháp là Sexual Wellness.
    2. **Phần thân bài (Deep Dive)**: 
       - Chia làm ít nhất 5-6 mục lớn (**Heading**).
       - Mỗi mục phân tích sâu về khía cạnh khoa học hoặc tâm lý.
       - LỒNG GHÉP SẢN PHẨM: Đồ chơi tình dục không phải là "thứ nhạy cảm", mà là "công cụ hỗ trợ sức khỏe". 
       - Ví dụ: "Máy rung không chỉ mang lại khoái cảm, mà còn giúp kích thích tuần hoàn máu vùng chậu, hỗ trợ phụ nữ dễ đạt đỉnh và giảm đau hành kinh..." 
       - Giới thiệu các dòng sản phẩm như: Máy rung massage, Trứng rung điều khiển từ xa, Máy tập Kegel, Gel bôi trơn gốc nước tinh khiết.
    3. **Ngôn từ (Tone & Voice)**: 
       - Tinh tế, sang trọng, mang tính giáo dục cao. 
       - Sử dụng các cụm từ: "Trợ thủ phòng the", "Vũ khí bí mật", "Trải nghiệm đa giác quan", "Nâng tầm bản lĩnh", "Chăm sóc sức khỏe thầm kín".
    4. **Tối ưu SEO**: Chèn từ khóa chính và phụ một cách tự nhiên. Sử dụng danh sách liệt kê (bullet points).
    5. **An toàn Google**: Không mô tả trần trụi các hành vi tình dục. Tập trung vào CẢM XÚC, LỢI ÍCH SỨC KHỎE và TRẢI NGHIỆM LIFESTYLE.
    6. **Hình ảnh**: Prompt hình ảnh mô tả không gian lãng mạn, sang trọng, hoặc các sản phẩm được chụp theo phong cách nghệ thuật (Artistic lifestyle).

    ĐỊNH DẠNG:
    - Sử dụng **Heading** (In đậm dòng tiêu đề).
    - Sau mỗi 3-4 đoạn văn, chèn một \`[PROMPT: mô tả ảnh minh họa bằng tiếng Anh]\`.
    - Bài viết phải đầy đủ: Giới thiệu, Nội dung chi tiết, Lời khuyên chuyên gia, Kết luận.`;

    const prompt = `Viết bài SEO 1500 chữ về: "${topic}". Lồng ghép các sản phẩm đồ chơi tình dục một cách chuyên nghiệp như một giải pháp wellness hàng đầu.`;

    try {
        const textResponse = await ai.models.generateContent({
            model: "gemini-3-pro-preview",
            contents: prompt,
            config: {
                systemInstruction: systemInstruction,
                responseMimeType: "application/json",
                responseSchema: articleSchema,
                temperature: 0.8,
            },
            safetySettings: safetySettings,
        });

        const parsedArticle: SeoArticle = JSON.parse(textResponse.text);

        // Process in-content images
        const contentWithPrompts = parsedArticle.content;
        const promptRegex = /\[PROMPT:\s*(.*?)\s*\]/g;
        const prompts = [...contentWithPrompts.matchAll(promptRegex)];

        if (prompts.length > 0) {
            const imageResults = await Promise.all(prompts.slice(0, 4).map(match => { // Limit to 4 images for performance
                return generateImageWithFlash(match[1]).then(imageUrl => ({
                    originalPrompt: match[0],
                    imageUrl: imageUrl,
                    promptText: match[1]
                }));
            }));

            let finalContent = contentWithPrompts;
            for (const result of imageResults) {
                if (result.imageUrl) {
                    const imgTag = `<div class="my-10"><img src="${result.imageUrl}" alt="${result.promptText.replace(/"/g, '&quot;')}" class="w-full rounded-2xl shadow-2xl border border-slate-700" /><p class="text-center text-sm text-slate-500 mt-3 italic">${result.promptText}</p></div>`;
                    finalContent = finalContent.replace(result.originalPrompt, imgTag);
                } else {
                    finalContent = finalContent.replace(result.originalPrompt, "");
                }
            }
            parsedArticle.content = finalContent;
        }

        // Featured Image
        if (parsedArticle.imagePrompt) {
            const imageUrl = await generateImageWithFlash(parsedArticle.imagePrompt + ", professional lifestyle photography, aesthetic, high-end");
            parsedArticle.imageUrl = imageUrl || 'https://placehold.co/1200x630/0f172a/e2e8f0/png?text=Sexual+Wellness+Premium';
        }

        return parsedArticle;
    } catch (e) {
        console.error("Gemini API Error:", e);
        throw new Error("Lỗi sáng tạo nội dung. Có thể chủ đề vi phạm chính sách an toàn nghiêm ngặt hoặc kết nối bị gián đoạn.");
    }
}

